body:
{
  "pains": [
    {
      "id": "pain:bill-outruns-the-system",
      "statement": "Our monitoring bill grew faster than the system it watches, and by the time we notice it's already bigger than the cloud bill.",
      "element": "b2b:table_stakes:acceptable_price",
      "shape": {
        "surface": "The observability invoice is a line item the size of, or larger than, the AWS bill it was supposed to help manage.",
        "operational": "Engineers spend whole sprints on cost reduction work - writing drop rules, cutting retention, arguing with the account manager - instead of shipping. Architecture decisions get vetoed by the pricing model rather than by engineering merit.",
        "personal": "The person who signed the contract has to defend a number they did not forecast and cannot explain, in front of finance, every quarter."
      },
      "workflow": "The monthly usage page in the vendor console, and the budget review where the observability line gets challenged. Also the moment a platform change ships and usage steps up with no warning and no cap.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "A traffic spike or a new service rollout multiplies hosts, containers or log volume and the next invoice steps up with no ceiling", "cites": ["src:3", "src:5"] },
        { "event": "A platform change that would cut cloud spend raises the observability bill instead, so the change gets shelved", "cites": ["src:5", "src:6"] },
        { "event": "Renewal quote arrives and finance asks why the number moved", "cites": ["src:2", "src:15"] }
      ],
      "who_feels": ["economic_buyer", "champion", "technical_evaluator"],
      "by_role": {
        "economic_buyer": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "We ended up having a Datadog bill that was higher than our AWS bill!", "cites": ["src:2"] },
            { "situation": "venting", "verbatim": "They had the opportunity to help us out - they ended up using it as leverage in their sales process, only willing to work with us IF we signed up for additional services... We tried to work with them, but eventually just ate the expense.", "cites": ["src:2"] }
          ],
          "costs_them": "A budget line that moves without a decision behind it, and a renewal negotiated from a position where walking away is not credible.",
          "fears": "Being the person who let a tooling line item eat a meaningful slice of the engineering budget while headcount was frozen.",
          "dream_outcome": "A bill they can forecast a year out, with a cap they set, that tracks the business rather than the log volume."
        },
        "champion": {
          "says": [
            { "situation": "venting", "verbatim": "Having recently dealt with a surprise runaway DataDog bill and personally completed lots of work to reduce our spend internally all I have to say is that their pricing is outrageously high and there is almost no way to put controls in place to prevent overspend.", "cites": ["src:3"] }
          ],
          "costs_them": "Weeks of their own time on spend reduction that produces no new capability.",
          "fears": "Recommending the tool, then owning the invoice that follows.",
          "dream_outcome": "Spend controls they can set themselves, before the overspend, not a reconciliation after it."
        },
        "technical_evaluator": {
          "says": [
            { "situation": "when_comparing", "verbatim": "Last I looked (and looked again just now), if we were to take all our structured logs from all services and send them to Datadog with our current retention policy, it would just about double our current IT spend.", "cites": ["src:4"] },
            { "situation": "when_refusing", "verbatim": "one personal case I can attest to was case the changes would halve the AWS bill but increase the DataDog bill by more than 10 times, a thousand percent", "cites": ["src:5"] }
          ],
          "costs_them": "Having to model vendor pricing as an input to architecture, which distorts the architecture.",
          "fears": "Picking a design that is correct technically and indefensible financially.",
          "dream_outcome": "Pricing that does not punish a container count, a scale-to-zero policy, or a service mesh."
        }
      },
      "segments": ["seg:platform", "seg:startup", "seg:enterprise"],
      "feature_ref": null,
      "feature_note": "No feature in brain/company addresses this - the answer is commercial, not functional: Grafana Cloud's free tier, usage-based pricing and per-signal billing. If Grafana Cloud's own pricing produces the same step changes, this pain is not killed, it is inherited.",
      "cites": ["src:2", "src:3", "src:4", "src:5", "src:18", "src:19"]
    },
    {
      "id": "pain:priced-out-of-the-data",
      "statement": "I'm deleting the telemetry I'd need to debug the outage, because keeping it costs more than the outage does.",
      "element": "b2b:ease_of_doing_business:information",
      "shape": {
        "surface": "Cardinality caps, sampling rates, ten histogram buckets, thirty-day retention - all set by what the bill tolerates rather than by what the system needs.",
        "operational": "The incident arrives and the label that would have identified the failing tenant was never collected, or the log line has already aged out. Debugging drops back to guessing and to grepping on the box.",
        "personal": "The on-call engineer has to say 'I don't have that data' on an incident bridge, which reads as not knowing their own system."
      },
      "workflow": "Writing relabel and drop rules in the collector config, choosing histogram buckets at instrumentation time, and setting retention in the vendor console - each one a bet about which future question is worth paying for.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "A cost reduction push lands and the first lever pulled is telemetry volume", "cites": ["src:3", "src:4"] },
        { "event": "A high-cardinality label (tenant id, customer id, pod name) is needed and the metrics backend refuses or prices it out", "cites": ["src:7"] },
        { "event": "Crash-restart loops or ephemeral containers generate billable units nobody budgeted for", "cites": ["src:5"] }
      ],
      "who_feels": ["technical_evaluator", "end_user", "champion"],
      "by_role": {
        "technical_evaluator": {
          "says": [
            { "situation": "when_comparing", "verbatim": "Every managed metrics system will put a limit on cardinality because all mainstream available metrics systems cost more per cardinality to query and store. If they don't limit that you can assume you or some other customer is going to use up the clusters resources and cause an outage.", "cites": ["src:7"] },
            { "situation": "when_it_bites", "verbatim": "They put limits on the numbers of unique containers you can have per host before charging container fees, so better hope you don't have too many crash-restart loops", "cites": ["src:5"] }
          ],
          "costs_them": "Instrumentation decisions made against a price sheet instead of against the failure modes they expect.",
          "fears": "The postmortem that ends in 'we didn't have the data', traced back to a drop rule they wrote.",
          "dream_outcome": "Keep every label and every line, and let the storage layer make it cheap rather than making them choose."
        },
        "champion": {
          "says": [
            { "situation": "when_refusing", "verbatim": "the last place couldn't because datadog apparently bills sidecar containers as additional hosts so using sidecar proxy would have doubled our datadog bill.", "cites": ["src:6"] }
          ],
          "costs_them": "A platform capability the team wanted, blocked by a billing unit.",
          "fears": "Being the reason the org cannot adopt a standard pattern.",
          "dream_outcome": "Telemetry priced on what is queried, not on how many processes happen to exist."
        }
      },
      "segments": ["seg:platform", "seg:enterprise"],
      "feature_ref": "feat:metrics",
      "cites": ["src:4", "src:5", "src:6", "src:7"]
    },
    {
      "id": "pain:paged-for-nothing",
      "statement": "I get woken up eight times a shift for things nobody acts on, and now I don't trust the page that actually matters.",
      "element": "b2b:individual:reduced_anxiety",
      "shape": {
        "surface": "A pager that fires repeatedly through the night on alerts the team has already agreed to ignore.",
        "operational": "Normalized deviance - the real signal is dismissed with 'we ignored that one last time'. On-call weeks produce no feature work, and the team quietly needs more people to cover the same load.",
        "personal": "Sleep deprivation with a measurable health cost, and attrition. People leave the rota, then leave the company."
      },
      "workflow": "The Alertmanager or PagerDuty push at 3am, then the scramble into a dashboard to establish that the threshold was meaningless, then back to bed and the same page an hour later.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "A bad shift - repeated pages across consecutive nights with no recovery time granted afterwards", "cites": ["src:9", "src:8"] },
        { "event": "An alert that has fired and been ignored enough times that the team stops reading it, right before it means something", "cites": ["src:8"] },
        { "event": "Someone resigns from the on-call rota or the company and names the pager in the exit conversation", "cites": ["src:9"] }
      ],
      "who_feels": ["end_user", "champion", "economic_buyer"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "venting", "verbatim": "Yeah I have a vivid memory of hysterically crying after getting less than 12 hours of sleep over 3 or 4 days during a particularly bad shift. My pager went off 30 minutes before the end of my shift and I lost it... Actually at that same company getting paged 8-10 times off-hours during an oncall shift was not unheard of, the burnout was real.", "cites": ["src:9"] },
            { "situation": "when_it_bites", "verbatim": "If you know you're in store for the same alert again and again, or perhaps even know that you know you're going to get paged, it's hard to think about anything else. It becomes then a game of normalizing deviance and burnout: \"oh, we just ignored that one last time\". Ok, why are they alerts then if they can be ignored? It's just going to murder people's spirit after a while.", "cites": ["src:8"] }
          ],
          "costs_them": "Sleep, health, and the ability to do focused work the following day.",
          "fears": "Missing the one real page because they have been trained by noise to dismiss it.",
          "dream_outcome": "A shift where the pager fires once or twice, and both times it was worth waking up for."
        },
        "champion": {
          "says": [
            { "situation": "to_their_boss", "verbatim": "This is the time where your mettle as a manager is really tested against your higher-ups. If your people are putting in unscheduled time, you better be ready to cough up something in return.", "cites": ["src:8"] }
          ],
          "costs_them": "Arguing for recovery time and headcount using anecdotes, because the alert data is not shaped to make the case.",
          "fears": "Losing the two people who actually know the system.",
          "dream_outcome": "Alert volume as a tracked, falling number they can show upward."
        }
      },
      "segments": ["seg:platform", "seg:startup", "seg:enterprise"],
      "feature_ref": "feat:irm",
      "cites": ["src:8", "src:9", "src:19"]
    },
    {
      "id": "pain:stack-needs-a-team",
      "statement": "Running our own observability stack quietly became a full-time team, and we still get paged for the monitoring system itself.",
      "element": "b2b:ease_of_doing_business:reduced_effort",
      "shape": {
        "surface": "A Grafana, Loki, Mimir and Prometheus deployment with dedicated headcount maintaining, upgrading and on-calling for it.",
        "operational": "Helm upgrades, Thanos capacity planning, chasing scaling bugs in open source components. The team that was supposed to be reducing toil now owns a distributed system of its own.",
        "personal": "The engineer who championed self-hosting owns it forever, and the on-call rota now includes the thing that is supposed to tell you what broke."
      },
      "workflow": "Upgrading the Loki or Mimir chart, sizing the metrics store before a growth quarter, and being paged because the telemetry backend fell over during the incident it was meant to explain.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "Metric volume or cardinality outgrows a single Prometheus and someone has to introduce Thanos or Mimir", "cites": ["src:13"] },
        { "event": "A small team tries to stand the stack up and finds the docs point at the hosted product", "cites": ["src:11"] },
        { "event": "Headcount review asks what the platform team is actually working on", "cites": ["src:12"] }
      ],
      "who_feels": ["technical_evaluator", "champion", "economic_buyer", "blocker"],
      "by_role": {
        "technical_evaluator": {
          "says": [
            { "situation": "when_comparing", "verbatim": "But now you need staffing/headcount to be experts in, and maintain, upgrade and be oncall for this stuff?", "cites": ["src:12"] }
          ],
          "costs_them": "Engineer-years spent on a system that produces no product value.",
          "fears": "Discovering that the true cost of self-hosting was never on the comparison slide.",
          "dream_outcome": "Keep the open source components and the query languages, hand the operations to someone else."
        },
        "end_user": {
          "says": [
            { "situation": "venting", "verbatim": "After many years with the comparative luxury of the stackdriver tools on GCP, I moved to a BigCorp with a grafana/loki/mimir system and a whole devops army to maintain it. For two years I've been unable to find anything positive to say about this experience. Our devops folks are super smart, so I can only conclude that the software sucks.", "cites": ["src:10"] }
          ],
          "costs_them": "A daily tool they cannot get answers out of, staffed by a team they cannot fault.",
          "fears": "That headcount is not the missing ingredient, so nothing will improve.",
          "dream_outcome": "The stack works well enough that the size of the team maintaining it stops being the topic."
        },
        "champion": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "It was not plug and play in any way. The docs kept saying this solution is not production ready even. I couldn't find the production guide, only the \"forget about self hosting and simply pay for us hosting this\".", "cites": ["src:11"] }
          ],
          "costs_them": "Weeks of evenings to reach a setup they still do not trust in production.",
          "fears": "Having built something they cannot hand to anyone else on the team.",
          "dream_outcome": "A path from self-hosted to hosted that does not require re-instrumenting anything."
        },
        "blocker": {
          "says": [
            { "situation": "when_refusing", "verbatim": "It's ironically cheaper to build a team of engineers that will maintain a sane observability stack instead of feeding the monster(s).", "cites": ["src:13"] }
          ],
          "costs_them": "Nothing yet - this is the position that blocks the purchase.",
          "fears": "Repeating the Datadog experience with a different logo, and losing the ability to fix things themselves.",
          "dream_outcome": "An open source stack they control, whose operating cost stays under the vendor quote."
        }
      },
      "segments": ["seg:startup", "seg:platform"],
      "feature_ref": null,
      "feature_note": "The thing that kills this is Grafana Cloud as a managed offering (prod:cloud), which is a product rather than any feature listed in brain/company. Note the same buyers supply the counter-argument: src:13 argues self-hosting headcount is still the cheaper path.",
      "cites": ["src:10", "src:11", "src:12", "src:13", "src:18", "src:19"]
    },
    {
      "id": "pain:tool-per-signal",
      "statement": "The answer is spread across five monitoring tools and three log systems, so every incident starts as a scavenger hunt.",
      "element": "b2b:ease_of_doing_business:integration",
      "shape": {
        "surface": "Separate products for metrics, logs and traces, often multiplied again per cloud and per acquired team.",
        "operational": "Request ids get copied between browser tabs, context is lost at each boundary, and the first twenty minutes of an incident go to locating the data rather than reading it.",
        "personal": "The responder looks slow in the incident channel while everyone watches them tab between tools."
      },
      "workflow": "The incident bridge: Slack, then the metrics dashboard to see the spike, then a separate log product to find the error, then a third tracing UI to follow the request - pasting identifiers across all three and hoping they correlate.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "Multi-cloud or multi-cluster growth leaves each environment with its own monitoring tool", "cites": ["src:16"] },
        { "event": "An incident where the trace id exists but the logs for it cannot be found", "cites": ["src:16", "src:19"] },
        { "event": "A consolidation or FinOps review counts the overlapping tools", "cites": ["src:16", "src:19"] }
      ],
      "who_feels": ["technical_evaluator", "end_user", "champion", "economic_buyer"],
      "by_role": {
        "technical_evaluator": {
          "says": [
            { "situation": "when_comparing", "verbatim": "\"5 different monitoring tools / 3 separate logging solutions\" - should be at most one for each case. 3 different cloud providers? So come up with a cloud-agnostic solution.", "cites": ["src:16"] },
            { "situation": "when_it_bites", "verbatim": "Currently support 20+ clusters with a team of 5 people across 2 clouds plus on-prem.", "cites": ["src:16"] }
          ],
          "costs_them": "Five integrations to maintain, five bills, and no single place where a question can be answered.",
          "fears": "Adding a sixth tool and calling it consolidation.",
          "dream_outcome": "One query surface across every cluster and cloud, where a trace, its logs and its metrics are one click apart."
        }
      },
      "segments": ["seg:platform", "seg:enterprise"],
      "feature_ref": "feat:dashboards",
      "cites": ["src:16", "src:19"]
    },
    {
      "id": "pain:spend-is-opaque",
      "statement": "I can't tell which team is generating the bill, so all I can do is cut across the board and hope.",
      "element": "b2b:ease_of_doing_business:transparency",
      "shape": {
        "surface": "One invoice, no per-team attribution, and a vendor usage page that does not answer 'who did this'.",
        "operational": "Cost control becomes a blanket retention cut applied to teams that were not the problem, while the team that was keeps going. Every engineer can raise the bill; nobody can be shown to have done it.",
        "personal": "The leader is asked in the budget review where the money went and does not have an answer they believe themselves."
      },
      "workflow": "The quarterly FinOps or budget review, working from a vendor usage page that breaks spend down by product line rather than by the team that generated it.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "Finance asks for a per-team breakdown of observability spend and none exists", "cites": ["src:15"] },
        { "event": "A cost reduction target lands with no way to target it, so it is applied uniformly", "cites": ["src:3", "src:15"] },
        { "event": "Renewal or a competitive review, where the incumbent's spend reporting is itself an objection", "cites": ["src:14"] }
      ],
      "who_feels": ["economic_buyer", "champion", "blocker"],
      "by_role": {
        "economic_buyer": {
          "says": [
            { "situation": "to_their_boss", "verbatim": "FinOps comes last, if there's even cost tracking per team in the observability suite.", "cites": ["src:15"] },
            { "situation": "venting", "verbatim": "It's yet another instance of Finance complaining that the transition to The Cloud gave every engineer a corporate credit card with no spend controls or a way for Finance to turn off the spigot.", "cites": ["src:15"] }
          ],
          "costs_them": "Authority over a budget they cannot actually steer.",
          "fears": "Cutting the wrong team's telemetry and owning the outage that follows.",
          "dream_outcome": "Spend attributed per team and per service, with a budget each team can see and be held to."
        },
        "technical_evaluator": {
          "says": [
            { "situation": "when_comparing", "verbatim": "Enterprises are growing tired of big observability platform lock-in, especially when it comes to Datadog's opaque nature of your spend on their products, for example.", "cites": ["src:14"] }
          ],
          "costs_them": "Time reverse-engineering a bill instead of reading a report.",
          "fears": "Recommending a platform whose billing they cannot explain to finance.",
          "dream_outcome": "Usage broken out by team, signal and service, visible before the invoice rather than after."
        }
      },
      "segments": ["seg:platform", "seg:enterprise"],
      "feature_ref": null,
      "feature_note": "Nothing in brain/company covers cost attribution or budget controls. Usage transparency and per-team spend reporting would kill this; if Grafana Cloud has them they are not listed, and if it does not, the pain survives a migration.",
      "cites": ["src:3", "src:14", "src:15", "src:19"]
    },
    {
      "id": "pain:locked-in-by-instrumentation",
      "statement": "Leaving means re-instrumenting a thousand services, so the vendor knows we can't actually walk.",
      "element": "b2b:ease_of_doing_business:flexibility",
      "shape": {
        "surface": "Hundreds or thousands of applications carrying a vendor-specific agent, with dashboards and alerts written in a proprietary query language.",
        "operational": "Any migration is a multi-quarter project touching every service repo, so the option is never seriously costed and the renewal is negotiated without leverage.",
        "personal": "The person who chose the vendor owns that choice for as long as they stay, and every price increase reflects on them."
      },
      "workflow": "The renewal negotiation, and the migration ticket that would have to touch every service's instrumentation, dashboards and alert rules at once.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "Renewal arrives with a price increase and the switching cost is scoped for the first time", "cites": ["src:14"] },
        { "event": "A team starts adopting OpenTelemetry specifically to make the backend replaceable", "cites": ["src:14", "src:19"] },
        { "event": "A cheaper backend is found and the blocker turns out to be the agent, not the data", "cites": ["src:20"] }
      ],
      "who_feels": ["technical_evaluator", "economic_buyer", "champion"],
      "by_role": {
        "technical_evaluator": {
          "says": [
            { "situation": "when_comparing", "verbatim": "When you instrument hundreds or thousands of applications with a specific tool, like the Datadog Agent, disentangling from that tool becomes nearly impossible without a massive investment of engineering time.", "cites": ["src:14"] }
          ],
          "costs_them": "A migration cost so large it removes the option to negotiate.",
          "fears": "Repeating the lock-in with the next vendor under a friendlier brand.",
          "dream_outcome": "Instrument once with OpenTelemetry and Prometheus, and treat the backend as replaceable."
        },
        "champion": {
          "says": [
            { "situation": "when_looking", "verbatim": "Last co we migrated all of our observability from Datadog to Grafana/AMP because it's much much cheaper. The vendor can charge some premium over the cost to build/maintain but not infinity.", "cites": ["src:20"] }
          ],
          "costs_them": "A migration they had to justify and run themselves.",
          "fears": "Having the same conversation again in three years.",
          "dream_outcome": "A backend they can leave, which is what keeps the price honest."
        }
      },
      "segments": ["seg:enterprise", "seg:platform"],
      "feature_ref": null,
      "feature_note": "The answer is Grafana's OpenTelemetry and Prometheus compatibility and its open source lineage, which brain/company does not list as a feature. Worth adding - src:19 shows 37% adopt OpenTelemetry specifically for freedom to switch vendors.",
      "cites": ["src:14", "src:19", "src:20"]
    },
    {
      "id": "pain:grafana-itself-is-abrasive",
      "statement": "Even with the stack running, the UI fights me hard enough that I go SSH into the box and grep instead.",
      "element": "b2b:individual:design_and_aesthetics",
      "shape": {
        "surface": "Query limits, dense configuration, and an interface people describe as dreadful after years of daily use.",
        "operational": "The tool gets bypassed. Senior engineers debug from the command line, junior engineers fight the query language, and the expensive central system is used by fewer people than it was bought for.",
        "personal": "The champion who rolled it out watches their own teammates refuse to open it, which reads as their judgment having been wrong."
      },
      "workflow": "Opening Explore to write a LogQL or PromQL query during an incident, hitting query limits or an unclear error, then abandoning it for kubectl logs and grep.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "A non-specialist teammate is asked to investigate a problem and will not open the tool at all", "cites": ["src:11"] },
        { "event": "A log query hits backend limits mid-incident and the responder falls back to the command line", "cites": ["src:21"] },
        { "event": "An engineer arrives from a cloud-native suite and compares the daily experience unfavourably", "cites": ["src:10"] }
      ],
      "who_feels": ["end_user", "champion", "technical_evaluator"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "venting", "verbatim": "The UX is dreadful? I could spend hours picking apart the terrible design decisions... But man oh man grafana is disappointing.", "cites": ["src:10"] },
            { "situation": "when_it_bites", "verbatim": "I usually parse prod logs and settings with command line while the younger guys trying to push through loki/grafana query limitations.", "cites": ["src:21"] }
          ],
          "costs_them": "Falling back to manual tooling on exactly the incidents where the platform was supposed to help.",
          "fears": "That the org keeps paying for a system they have privately stopped using.",
          "dream_outcome": "Getting an answer out of the UI faster than they could get it by SSHing to the box."
        },
        "champion": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "After I deployed it the UX was so abrasive my partner won't even try to go into it to figure out a problem.", "cites": ["src:11"] }
          ],
          "costs_them": "Adoption. The stack works and nobody uses it.",
          "fears": "Being the only person in the company who can operate the observability tooling.",
          "dream_outcome": "Someone who has never seen the tool can find a problem in it without being trained first."
        }
      },
      "segments": ["seg:startup", "seg:platform", "seg:enterprise"],
      "feature_ref": null,
      "feature_note": "This is a pain Grafana's own product causes, so no feature in brain/company kills it. It is the objection the sale has to answer, and it appears in the same threads where buyers are otherwise arguing in Grafana's favour on cost.",
      "cites": ["src:10", "src:11", "src:21"]
    },
    {
      "id": "pain:retention-vs-compliance",
      "statement": "Audit wants years of logs retained and resident in-region, the budget wants thirty days, and I'm the one who has to pick.",
      "element": "b2b:table_stakes:regulatory_compliance",
      "shape": {
        "surface": "Retention set to the shortest window the auditors will tolerate, because the next tier costs more than the risk appears to.",
        "operational": "Tokenization of anything touching PII before it leaves the app, data residency written into the storage decision, and a separate archive path for the records compliance actually asks for.",
        "personal": "The security or compliance owner signs off on a retention window they know is the budget's number rather than the policy's number."
      },
      "workflow": "The vendor security review and the retention policy conversation, where storage cost per GB per month is multiplied by the audit requirement and comes back unaffordable.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        { "event": "An audit or customer security questionnaire asks for a retention schedule and a residency guarantee", "cites": ["src:17"] },
